from pathlib import Path
p=Path('ClockTimer.js')
s=p.read_text()
s=s.replace('''                    box-shadow:\n                        inset 0 0 clamp(12px, 5cqi, 30px)\n                            rgb(0 0 0 / calc(\n                                var(--clock-timer-glass-vignette-opacity) * 0.38\n                            )),\n                        inset 0 clamp(1px, 0.5cqi, 3px) clamp(4px, 1.6cqi, 10px)\n                            rgb(255 255 255 / calc(\n                                var(--clock-timer-glass-edge-opacity) * 0.72\n                            ));''','''                    box-shadow:\n                        inset 0 0 clamp(12px, 5cqi, 30px)\n                            rgb(0 0 0 / calc(\n                                var(--clock-timer-glass-vignette-opacity) * 0.72\n                            )),\n                        inset 0 clamp(1px, 0.5cqi, 3px) clamp(4px, 1.6cqi, 10px)\n                            rgb(255 255 255 / calc(\n                                var(--clock-timer-glass-edge-opacity) * 0.95\n                            )),\n                        inset 0 0 0 clamp(1px, 0.45cqi, 2px)\n                            rgb(0 0 0 / calc(\n                                var(--clock-timer-glass-edge-opacity) * 0.34\n                            ));''',1)
s=s.replace('''                        linear-gradient(\n                            145deg,\n                            rgb(255 255 255 / 18%) 0%,\n                            transparent 34%,\n                            transparent 68%,\n                            rgb(255 255 255 / 6%) 100%\n                        );\n                    opacity:\n                        var(--clock-timer-glass-highlight-opacity);\n                    mix-blend-mode: screen;''','''                        linear-gradient(\n                            145deg,\n                            rgb(255 255 255 / 32%) 0%,\n                            transparent 34%,\n                            transparent 64%,\n                            rgb(0 0 0 / 10%) 100%\n                        );\n                    opacity:\n                        var(--clock-timer-glass-highlight-opacity);''',1)
s=s.replace('''                            transparent 52%,\n                            rgb(0 0 0 / 8%) 78%,\n                            rgb(0 0 0 / 20%) 100%''','''                            transparent 48%,\n                            rgb(0 0 0 / 14%) 76%,\n                            rgb(0 0 0 / 34%) 100%''',1)
s=s.replace('''                            rgb(255 255 255 / 8%) 0%,\n                            transparent 24%,\n                            transparent 72%,\n                            rgb(0 0 0 / 10%) 100%''','''                            rgb(255 255 255 / 24%) 0%,\n                            transparent 26%,\n                            transparent 68%,\n                            rgb(0 0 0 / 18%) 100%''',1)
p.write_text(s)
